def temperer(p, T):
    if T == 0:
        best = 0
        for i in range(1, len(p)):
            if p[i] > p[best]:
                best = i
        return [1.0 if i == best else 0.0 for i in range(len(p))]
    q = [x ** (1.0 / T) for x in p]
    s = sum(q)
    return [round(x / s, 4) for x in q]

def tirer(p, u):
    cumul = 0.0
    for i, x in enumerate(p):
        cumul += x
        if u <= cumul:
            return i
    return len(p) - 1

from math import exp, log

def apprendre(corpus, lissage):
    alphabet = sorted(set(corpus))
    n = len(alphabet)
    comptes = {a: {b: 0 for b in alphabet} for a in alphabet}
    for i in range(len(corpus) - 1):
        comptes[corpus[i]][corpus[i + 1]] += 1
    table = {}
    for a in alphabet:
        total = sum(comptes[a].values()) + lissage * n
        if total == 0:
            table[a] = {b: 1.0 / n for b in alphabet}   # aucune transition observee
        else:
            table[a] = {b: (comptes[a][b] + lissage) / total for b in alphabet}
    return (alphabet, table)

def perplexite(texte, alphabet, table):
    if len(texte) < 2:
        return 0.0
    somme, n = 0.0, 0
    for i in range(len(texte) - 1):
        a, b = texte[i], texte[i + 1]
        p = table.get(a, {}).get(b, 0.0)
        if p <= 0:
            return float('inf')
        somme += -log(p)
        n += 1
    return round(exp(somme / n), 4)
